<script setup lang="ts">
import { computed, ref } from 'vue'; import AppCard from '../../components/AppCard.vue'; import PrimaryButton from '../../components/PrimaryButton.vue'; import { commerceRepository } from '../../services/mock/repositories'; import type { ServicePlan } from '../../types/domain'; import { uniApi as uni } from '../../services/platform/uni'
const plans = ref<ServicePlan[]>([]); const route = (getCurrentPages().at(-1) as any)?.options as Record<string, string> | undefined; commerceRepository.listPlans().then(x => { plans.value = x }); const addon = computed<ServicePlan | undefined>(() => route?.name ? { id: 'addon-' + route.name, name: decodeURIComponent(route.name), level: '初级', cycle: '月', priceFen: Number(route.price || 0), description: '专项健康增值服务' } : undefined); const plan = computed(() => addon.value || plans.value.find(x => x.id === route?.planId) || plans.value[0]); const pay = async () => { if (!plan.value) return; await commerceRepository.createMockOrder(plan.value); uni.showToast({ title: 'Mock支付成功' }); setTimeout(() => uni.navigateTo({ url: '/pages/orders/index' }), 500) }
</script>
<template><view class="page"><view class="topbar"><text class="back" @click="uni.navigateBack()">‹</text><text class="top-title">订单确认</text><text>♧</text></view><AppCard class="product"><view class="avatar">李</view><view class="grow"><text class="name">{{ plan?.name || '健康管理服务' }}</text><text class="muted">李晓雯 · 专属健康管理师</text></view><text class="price">¥{{ (plan?.priceFen || 0) / 100 }}</text></AppCard><view class="section-title">服务内容</view><AppCard><text v-for="x in ['健康档案建立与分析','定制化健康改善计划','每日健康打卡与提醒','每月1次1V1咨询','专属健康管理师']" :key="x" class="check">✓　{{ x }}</text></AppCard><view class="section-title">支付方式</view><AppCard><view class="pay-row">微信支付 <text>●</text></view><view class="pay-row">支付宝支付 <text>○</text></view></AppCard><view class="pay-bar"><view><text class="muted">应付金额</text><text class="total">¥{{ (plan?.priceFen || 0) / 100 }}</text></view><PrimaryButton label="立即支付" @tap="pay" /></view></view></template>
